    directorySection=new LinearLayout(this);directorySection.setOrientation(1);add(box,directorySection);add(directorySection,text("文件存入目录",18));directoryPath=text("连接文件池后选择目录",14);directoryPath.setTextIsSelectable(true);add(directorySection,directoryPath);LinearLayout folderActions=new LinearLayout(this);add(directorySection,folderActions);chooseDirectory=new Button(this);chooseDirectory.setText("选择 / 最近");chooseDirectory.setContentDescription("选择共享目录或最近目录");newDirectory=new Button(this);newDirectory.setText("新建");newDirectory.setContentDescription("在当前目录下新建目录");refreshDirectory=new Button(this);refreshDirectory.setText("刷新");for(Button action:new Button[]{chooseDirectory,newDirectory,refreshDirectory}){action.setTextSize(14);action.setMinWidth(0);action.setMinimumWidth(0);folderActions.addView(action,new LinearLayout.LayoutParams(0,-2,action==chooseDirectory?2:1));}chooseDirectory.setOnClickListener(v->chooseDirectory());newDirectory.setOnClickListener(v->newDirectory());refreshDirectory.setOnClickListener(v->refreshDirectory(null));
    skipDuplicates=new CheckBox(this);skipDuplicates.setText("发现文件池已有相同原件时跳过上传（同一目录、同一接收范围）");skipDuplicates.setChecked(true);add(box,skipDuplicates);status=text("",14);status.setTextIsSelectable(true);add(box,status);send=new Button(this);send.setText("确认加入后台传输");send.setEnabled(false);add(box,send);Button back=new Button(this);back.setText("返回 / 取消分享");back.setOnClickListener(v->finish());add(box,back);
    add(box,text("原件先保存到应用私有缓存并校验，再加密发送。离开页面后由通知显示进度；可暂停、恢复或取消。系统强行停止应用后，需要重新打开应用恢复已缓存任务。",12));
