  private void prepareSourceSummary(TextView view){validInput=false;busy(false);view.setText("正在读取来源名称和大小…");new Thread(()->{try{StringBuilder names=new StringBuilder();long total=0;boolean unknown=false;int count=0;if(folderTree!=null){for(SafTreeFiles.Entry item:SafTreeFiles.scan(getContentResolver(),folderTree)){if(names.length()<1600)names.append(item.directory?"目录 · ":"文件 · ").append(item.path).append('\n');if(!item.directory){count++;long size=sourceSize(item.uri);if(size<0)unknown=true;else total=Math.addExact(total,size);}}}else{for(Uri uri:inputs){String name="文件";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}if(names.length()<1600)names.append(name).append('\n');count++;long size=sourceSize(uri);if(size<0)unknown=true;else total=Math.addExact(total,size);}}if(sharedText!=null)names.append("文字：").append(sharedText.substring(0,Math.min(120,sharedText.length()))).append('\n');String ready=(folderTree==null?"":"所选目录内容：\n")+names+"\n共 "+count+" 个文件 · 已知大小 "+android.text.format.Formatter.formatFileSize(this,total)+(unknown?"（部分来源未提供大小）":"");runOnUiThread(()->{if(destroyed)return;sourceSummary=ready;view.setText(ready);validInput=true;busy(false);});}catch(Exception error){runOnUiThread(()->{if(!destroyed){view.setText("无法核对来源，请重新选择文件："+UploadQueueService.message(error));validInput=false;busy(false);}});}},"relay-share-source-summary").start();}
  private long sourceSize(Uri uri){try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()&&!c.isNull(0))return c.getLong(0);}catch(Exception ignored){}return -1;}
  private void readIntent(Intent intent)throws Exception{if(!Intent.ACTION_SEND.equals(intent.getAction())&&!Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction()))throw new IOException("请从系统分享菜单或后台发送入口选择文件。");CharSequence chars=intent.getCharSequenceExtra(Intent.EXTRA_TEXT);if(chars!=null&&!chars.toString().trim().isEmpty()){sharedText=chars.toString();if(sharedText.length()>20000||sharedText.indexOf('\0')>=0)throw new IOException("文字最多 20,000 字符。");}LinkedHashSet<Uri> unique=new LinkedHashSet<>();if(Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction())){ArrayList<Uri> list=intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(list!=null)unique.addAll(list);}else{Uri uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null)unique.add(uri);}ClipData clip=intent.getClipData();if(clip!=null){if(clip.getItemCount()>100)throw new IOException("一次最多 100 个文件。");for(int i=0;i<clip.getItemCount();i++){Uri uri=clip.getItemAt(i).getUri();if(uri!=null)unique.add(uri);}}if(unique.size()>100)throw new IOException("一次最多 100 个文件。");for(Uri uri:unique){if(uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null)throw new IOException("仅接受系统授权的 content 文件。");inputs.add(uri);}if(inputs.isEmpty()&&sharedText==null)throw new IOException("没有可分享的内容。");}
  private String target(){int position=recipients.getSelectedItemPosition();return folderTree==null&&position>=0&&position<targets.size()?targets.get(position):null;}
  private static String identity(ShareConnectionStore.Entry entry){return entry.serverId+"|"+entry.fingerprint;}
  private boolean hasFiles(){return folderTree!=null||!inputs.isEmpty();}
  private void updateDirectoryControls(){boolean shared=target()==null,connected=selected!=null&&folderSnapshot!=null;directorySection.setVisibility(hasFiles()?View.VISIBLE:View.GONE);chooseDirectory.setEnabled(!busy&&connected&&shared);newDirectory.setEnabled(!busy&&connected&&shared&&folderValid);refreshDirectory.setEnabled(!busy&&connected&&shared);if(!connected)directoryPath.setText("连接文件池后选择目录");else if(!shared)directoryPath.setText("定向发送：指定设备、发送者和文件池管理员可查看；不进入共享目录。");else if(!folderValid)directoryPath.setText("原目录已删除或不可用，请重新选择目录。不会自动改存根目录。");else try{directoryPath.setText(folderSnapshot.get(folderId).toString());}catch(Exception ignored){}send.setEnabled(!busy&&validInput&&connected&&(!shared||!hasFiles()||folderValid));}
  private void busy(boolean value){busy=value;stations.setEnabled(!value);address.setEnabled(!value);code.setEnabled(!value);connect.setEnabled(!value&&validInput);skipDuplicates.setEnabled(!value);recipients.setEnabled(!value&&selected!=null&&folderTree==null);updateDirectoryControls();}
  private void connect(){if(busy||!validInput)return;String raw=address.getText().toString().trim(),pairCode=code.getText().toString().trim(),previousIdentity=selected==null?null:identity(selected),previousTarget=selected==null?null:target();selected=null;busy(true);status.setText("正在验证接收设备身份…");new Thread(()->{try{
      long operationEpoch=RemoteManager.epoch();String host=ShareConnectionStore.origin(raw);JSONObject remoteProfile=new RemoteConnections(this).atOrigin(host);boolean remoteConnection=remoteProfile!=null;ShareConnectionStore.Entry entry=ShareConnectionStore.ownLoopback(host)?ShareConnectionStore.local():store.findOrigin(host);TlsIdentity.Peer peer=null;
      if(!ShareConnectionStore.ownLoopback(host)){if(remoteProfile!=null){JSONObject invitation=remoteProfile.getJSONObject("invite");RemoteManager.ensure(this,invitation.getString("serverId"),invitation.getString("fingerprint"));if(entry!=null&&(!entry.serverId.equals(invitation.getString("serverId"))||!entry.fingerprint.equals(invitation.getString("fingerprint"))))throw new IOException("远程端口对应的可信身份不一致，连接已阻止。");}if(entry!=null){entry=TrustedDiscovery.verifyOrReconnect(this,entry);host=entry.origin;remoteConnection=remoteConnection||new RemoteConnections(this).atOrigin(host)!=null;peer=TlsIdentity.probe(host,entry.fingerprint,entry.serverId);}else{JSONObject invitation=remoteProfile==null?null:remoteProfile.getJSONObject("invite");peer=TlsIdentity.probe(host,invitation==null?null:invitation.getString("fingerprint"),invitation==null?null:invitation.getString("serverId"));ShareConnectionStore.Entry same=store.findId(peer.serverId);if(same!=null){if(!same.fingerprint.equals(peer.fingerprint))throw new javax.net.ssl.SSLPeerUnverifiedException("设备证书发生变化。请回首页移除旧的可信设备，再核对主机指纹重新配对。");entry=RemoteManager.relocate(this,same,peer,operationEpoch,remoteConnection);}else if(!TrustPrompt.confirm(this,peer))throw new IOException("未确认设备身份，未发送配对码或文件。");}RemoteManager.verified(this,peer,operationEpoch,remoteConnection);}
      if(destroyed)return;String credential=entry==null?null:entry.token,fp=peer==null?entry.fingerprint:peer.fingerprint;
      if(credential==null||!pairCode.isEmpty()){if(!pairCode.matches("[0-9]{6}"))throw new IOException("请输入中转站显示的 6 位配对码。");ShareTransport client=new ShareTransport(host,null,fp);active=client;credential=client.request("/api/pair","POST",new JSONObject().put("code",pairCode).put("name",Build.MODEL+" 分享")).getString("token");}
      ShareTransport client=new ShareTransport(host,credential,fp);active=client;JSONObject state=client.request("/api/state","GET",null);String name=state.getJSONObject("network").optString("hostname","中转站");if(destroyed)return;if(peer!=null)RemoteManager.remember(this,peer,name,credential,operationEpoch,remoteConnection);else store.put(host,name,credential);ShareConnectionStore.Entry ready=ShareConnectionStore.ownLoopback(host)?ShareConnectionStore.local():store.findOrigin(host);if(ready==null)throw new IOException("可信连接未保存，请重新连接。");ShareDirectorySupport.verifyIdentity(state,ready);ShareDirectorySupport.Snapshot snapshot=new ShareDirectorySupport.Snapshot(state);
      runOnUiThread(()->{if(destroyed)return;selected=ready;selectedDeviceId=state.optJSONObject("device").optString("id");folderSnapshot=snapshot;String oldIdentity=folderIdentity;folderIdentity=identity(ready);boolean preferredPool=raw.equals(getIntent().getStringExtra("preferredOrigin"));if(!folderIdentity.equals(oldIdentity)){ArrayList<String> recent=directories.recent(ready,snapshot);folderId=preferredPool&&getIntent().hasExtra("folderId")?getIntent().getStringExtra("folderId"):recent.isEmpty()?null:recent.get(0);}folderValid=snapshot.has(folderId);ArrayList<String> labels=new ArrayList<>();targets.clear();labels.add("共享文件池 · 所有已连接设备可查看");targets.add(null);JSONArray devices=state.optJSONArray("devices");JSONObject selfDevice=state.optJSONObject("device");String self=selfDevice==null?"":selfDevice.optString("id");if(devices!=null)for(int i=0;i<devices.length();i++){JSONObject d=devices.optJSONObject(i);if(d!=null&&!d.optBoolean("revoked")&&!self.equals(d.optString("id"))){labels.add("仅发送给："+d.optString("name"));targets.add(d.optString("id"));}}recipients.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,labels));String preferred=folderIdentity.equals(previousIdentity)?previousTarget:preferredPool?getIntent().getStringExtra("preferredTarget"):null;boolean targetFound=preferred==null;for(int i=0;i<targets.size();i++)if(preferred!=null&&preferred.equals(targets.get(i))){recipients.setSelection(i);targetFound=true;}if(!targetFound&&folderTree==null){selected=null;busy(false);status.setText("原接收设备已被移除，未改为共享发送。请返回文件池重新选择接收设备。");return;}busy(false);status.setText("已验证 "+name+"，请核对接收范围"+(hasFiles()?"和保存目录":"")+"。");});
    }catch(Exception e){runOnUiThread(()->{if(!destroyed){busy(false);status.setText(UploadQueueService.message(e));}});}finally{active=null;}},"relay-share-secure-connect").start();}
  private ShareConnectionStore.Entry currentEntry(ShareConnectionStore.Entry expected)throws Exception {ShareConnectionStore.Entry local=ShareConnectionStore.local(),current=local!=null&&local.serverId.equals(expected.serverId)?local:store.findId(expected.serverId);if(current==null||!current.fingerprint.equals(expected.fingerprint))throw new javax.net.ssl.SSLPeerUnverifiedException("可信连接已变化，请重新确认接收设备。");return TrustedDiscovery.verifyOrReconnect(this,current);}
  private void chooseDirectory(){if(busy||selected==null||folderSnapshot==null||target()!=null)return;LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(16),dp(4),dp(16),0);EditText search=new EditText(this);search.setSingleLine();search.setHint("搜索完整目录路径");box.addView(search);ListView list=new ListView(this);box.addView(list,new LinearLayout.LayoutParams(-1,dp(340)));ArrayList<ShareDirectorySupport.Folder> options=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,labels);list.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("选择共享目录").setView(box).setNegativeButton("取消",null).create();ArrayList<String> recent=directories.recent(selected,folderSnapshot);Runnable filter=()->{String query=search.getText().toString().toLowerCase(Locale.ROOT);options.clear();labels.clear();Set<String> used=new HashSet<>();for(String id:recent){try{ShareDirectorySupport.Folder f=folderSnapshot.get(id);if(f.toString().toLowerCase(Locale.ROOT).contains(query)){options.add(f);labels.add("最近 · "+f);used.add(id==null?"":id);}}catch(Exception ignored){}}for(ShareDirectorySupport.Folder f:folderSnapshot.ordered)if(!used.contains(f.id==null?"":f.id)&&f.toString().toLowerCase(Locale.ROOT).contains(query)){options.add(f);labels.add(f.toString());}adapter.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filter.run();}public void afterTextChanged(Editable s){}});list.setOnItemClickListener((p,v,position,id)->{folderId=options.get(position).id;folderValid=true;updateDirectoryControls();status.setText("目录已选择，发送前将再次核验接收范围和目录。");dialog.dismiss();});filter.run();dialog.show();}
  private void newDirectory(){if(busy||selected==null||!folderValid||target()!=null)return;EditText name=new EditText(this);name.setSingleLine();name.setHint("例如：本周课件");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("在当前目录下新建").setMessage(directoryPath.getText()).setView(name).setNegativeButton("取消",null).setPositiveButton("创建并选中",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{try{String value=SafTreeFiles.segment(name.getText().toString());dialog.dismiss();refreshDirectory(value);}catch(Exception error){name.setError(UploadQueueService.message(error));}}));dialog.show();}
  private void refreshDirectory(String createName){if(busy||selected==null||target()!=null)return;ShareConnectionStore.Entry expected=selected;String parent=folderId;busy(true);status.setText(createName==null?"正在刷新共享目录…":"正在创建目录…");new Thread(()->{try{ShareConnectionStore.Entry entry=currentEntry(expected);ShareTransport client=new ShareTransport(entry);active=client;JSONObject state=client.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(state,entry);ShareDirectorySupport.Snapshot snapshot=new ShareDirectorySupport.Snapshot(state);String next=parent;if(createName!=null){snapshot.get(parent);next=client.request("/api/folders/ensure","POST",new JSONObject().put("parentId",parent==null?JSONObject.NULL:parent).put("path",new JSONArray().put(createName))).getString("folderId");state=client.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(state,entry);snapshot=new ShareDirectorySupport.Snapshot(state);snapshot.get(next);}ShareDirectorySupport.Snapshot ready=snapshot;String destination=next;runOnUiThread(()->{if(destroyed)return;selected=entry;folderSnapshot=ready;folderId=destination;folderValid=ready.has(folderId);busy(false);status.setText(folderValid?(createName==null?"目录已刷新，请核对完整路径。":"目录已创建并选中。请确认加入后台传输。"):"原目录已删除，请重新选择；未自动改存根目录。");});}catch(Exception error){runOnUiThread(()->{if(!destroyed){busy(false);status.setText(UploadQueueService.message(error));}});}finally{active=null;}},"relay-share-directory").start();}
  private void enqueue(){if(busy||selected==null||!validInput||hasFiles()&&target()==null&&!folderValid)return;ShareConnectionStore.Entry expected=selected;String recipient=target(),destination=recipient==null&&hasFiles()?folderId:null;boolean skip=skipDuplicates.isChecked();String path;try{path=recipient==null&&hasFiles()?folderSnapshot.get(destination).path:null;}catch(Exception error){status.setText(UploadQueueService.message(error));return;}busy(true);status.setText("发送前正在核验接收设备和保存目录…");new Thread(()->{try{ShareConnectionStore.Entry entry=currentEntry(expected);ShareTransport client=new ShareTransport(entry);active=client;JSONObject state=client.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(state,entry);if(!state.getJSONObject("device").getString("id").equals(selectedDeviceId))throw new IOException("配对身份已改变，请重新连接并确认发送。");ShareDirectorySupport.Snapshot snapshot=new ShareDirectorySupport.Snapshot(state);try{ShareDirectorySupport.validateDestination(state,snapshot,recipient,destination);}catch(Exception error){runOnUiThread(()->{if(destroyed)return;folderSnapshot=snapshot;folderValid=snapshot.has(folderId);if(recipient!=null)selected=null;busy(false);status.setText(UploadQueueService.message(error));});return;}if(path!=null&&!path.equals(snapshot.get(destination).path)){runOnUiThread(()->{if(destroyed)return;folderSnapshot=snapshot;folderValid=true;busy(false);status.setText("目录名称或位置已改变，请核对上方完整路径，再次确认发送。");});return;}currentEntry(entry);if(destroyed)return;runOnUiThread(()->{if(destroyed)return;try{selected=entry;folderSnapshot=snapshot;queue(entry,recipient,destination,skip);if(recipient==null&&hasFiles())try{directories.remember(entry,snapshot,destination);}catch(Exception ignored){}startActivity(new Intent(this,TransferQueueActivity.class));finish();}catch(Exception error){busy(false);status.setText(UploadQueueService.message(error));}});}catch(Exception error){runOnUiThread(()->{if(!destroyed){busy(false);status.setText(UploadQueueService.message(error));}});}finally{active=null;}},"relay-share-preflight").start();}
  private void queue(ShareConnectionStore.Entry entry,String target,String destination,boolean skip)throws Exception {if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},71);Intent queue=new Intent(this,UploadQueueService.class).setAction(UploadQueueService.ENQUEUE).putExtra("serverId",entry.serverId).putExtra("deviceId",selectedDeviceId).putExtra("fingerprint",entry.fingerprint).putExtra("targetId",target).putExtra("folderId",destination).putExtra("skipDuplicates",skip).putExtra("text",sharedText).putParcelableArrayListExtra("uris",inputs);if(folderTree!=null){queue.putExtra("folderTree",folderTree.toString()).setClipData(ClipData.newRawUri("待发送目录",folderTree));queue.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);}else if(!inputs.isEmpty()){ClipData clip=ClipData.newUri(getContentResolver(),"待发送原件",inputs.get(0));for(int i=1;i<inputs.size();i++)clip.addItem(new ClipData.Item(inputs.get(i)));queue.setClipData(clip);queue.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);}startForegroundService(queue);}
  @Override protected void onDestroy(){destroyed=true;ShareTransport client=active;if(client!=null)client.cancel();super.onDestroy();}
